import type { BankQuestion } from "@/lib/bank";

/** Solutions and States of Matter (Chemistry (JEE/NEET)): 117 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"chem-solutions-states-1","question":"According to Raoult's law, the relative lowering of vapour pressure of a dilute solution of a non-volatile solute is equal to:","options":["The mole fraction of the solute","The molality of the solute","The molarity of the solute","The mole fraction of the solvent"],"answer":0,"explanation":"(p° − p)/p° = x(solute). It equals the mole fraction of the solute, not of the solvent; molality appears only in the approximate dilute form after multiplying by M(solvent).","difficulty":"easy","source":"NEET"},
  {"id":"chem-solutions-states-2","question":"Assuming complete dissociation, the van 't Hoff factor (i) of K₂SO₄ in water is:","options":["1","2","3","4"],"answer":2,"explanation":"K₂SO₄ → 2K⁺ + SO₄²⁻ gives 3 ions per formula unit, so i = 3.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-3","question":"At constant temperature, the volume of a fixed mass of gas is inversely proportional to its pressure. This is:","options":["Avogadro's law","Boyle's law","Charles's law","Gay-Lussac's law"],"answer":1,"explanation":"Boyle's law: PV = constant at fixed n and T. Charles's law relates V and T at constant P.","difficulty":"easy","source":"NEET"},
  {"id":"chem-solutions-states-4","question":"A fixed amount of gas occupies 2.0 L at 300 K. At the same pressure, its volume at 450 K is:","options":["2.25 L","4.5 L","1.33 L","3.0 L"],"answer":3,"explanation":"Charles's law: V₂ = V₁ × T₂/T₁ = 2.0 × 450/300 = 3.0 L. Dividing the other way (1.33 L) is the usual slip.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-5","question":"A 0.1 molal aqueous solution of glucose is prepared (Kb of water = 0.52 K kg mol⁻¹). Its boiling point at 1 atm is:","options":["100.52 °C","100.052 °C","100.104 °C","99.948 °C"],"answer":1,"explanation":"ΔTb = i·Kb·m = 1 × 0.52 × 0.1 = 0.052 K, so Tb = 100.052 °C. Glucose does not ionise, so i = 1 (100.104 °C would need i = 2).","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-6","question":"Which of the following liquid pairs shows a positive deviation from Raoult's law?","options":["Phenol + aniline","Chloroform + acetone","Nitric acid + water","Acetone + carbon disulphide"],"answer":3,"explanation":"In acetone + CS₂ the A–B attractions are weaker than A–A and B–B, so the vapour pressure is higher than predicted. The other three pairs form stronger A–B interactions (H-bonding) and show negative deviation.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-solutions-states-7","question":"At the same temperature, the ratio of the root-mean-square speed of H₂ molecules to that of O₂ molecules is:","options":["1 : 16","16 : 1","1 : 4","4 : 1"],"answer":3,"explanation":"u(rms) = √(3RT/M), so u(H₂)/u(O₂) = √(32/2) = √16 = 4. The ratio 16 : 1 forgets the square root.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-8","question":"Henry's law is written as p = K_H·x, where x is the mole fraction of the dissolved gas. Which statement is correct?","options":["The solubility of a gas in water increases with rise in temperature","K_H is independent of temperature","At a given temperature, a gas with a higher K_H is more soluble","At a given temperature, a gas with a higher K_H is less soluble"],"answer":3,"explanation":"For a fixed partial pressure, x = p/K_H, so a larger K_H means a smaller mole fraction dissolved. K_H rises with temperature, which is why gas solubility falls on heating.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-solutions-states-9","question":"The osmotic pressure of a 0.1 M aqueous glucose solution at 300 K is (R = 0.0821 L atm K⁻¹ mol⁻¹):","options":["0.246 atm","1.23 atm","24.6 atm","2.46 atm"],"answer":3,"explanation":"π = CRT = 0.1 × 0.0821 × 300 = 2.46 atm (glucose: i = 1).","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-10","question":"For H₂ and He at room temperature, the compressibility factor Z is greater than 1 at all pressures. The reason is that:","options":["Their molecules have zero volume","They are below their Boyle temperature at room temperature","Their intermolecular attractions (van der Waals a) are very small, so the excluded-volume term b dominates","They have very large values of a"],"answer":2,"explanation":"With a ≈ 0, Z ≈ 1 + Pb/RT > 1. Room temperature is well above the Boyle temperatures of H₂ and He, so they never show the dip below Z = 1 there.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-11","question":"Van der Waals constants a (in atm L² mol⁻²) are: NH₃ 4.17, CO₂ 3.59, N₂ 1.39, H₂ 0.244. Which gas is liquefied most easily?","options":["H₂","CO₂","NH₃","N₂"],"answer":2,"explanation":"A larger a means stronger intermolecular attraction and a higher critical temperature (Tc = 8a/27Rb), so NH₃ liquefies most easily.","difficulty":"hard","source":"NEET"},
  {"id":"chem-solutions-states-12","question":"Benzene (p° = 150 mm Hg) and toluene (p° = 50 mm Hg) form an ideal solution. For an equimolar liquid mixture, the mole fraction of benzene in the vapour is:","options":["0.50","0.25","0.75","0.60"],"answer":2,"explanation":"p(benzene) = 0.5 × 150 = 75 mm, p(toluene) = 0.5 × 50 = 25 mm, total = 100 mm. y(benzene) = 75/100 = 0.75: the vapour is richer in the more volatile component.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-13","question":"0.585 g of NaCl (molar mass 58.5 g/mol) is dissolved in 100 g of water. Assuming complete dissociation (Kf = 1.86 K kg mol⁻¹), the freezing point of the solution is:","options":["−3.72 °C","−0.186 °C","−0.372 °C","−0.744 °C"],"answer":2,"explanation":"m = 0.01 mol/0.1 kg = 0.1 m; ΔTf = i·Kf·m = 2 × 1.86 × 0.1 = 0.372 K. Forgetting i = 2 gives −0.186 °C.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-14","question":"5 g of a polymer dissolved in 1 L of solution shows an osmotic pressure of 0.0123 atm at 300 K (R = 0.0821 L atm K⁻¹ mol⁻¹). The molar mass of the polymer is about:","options":["1.0 × 10³ g/mol","1.0 × 10⁴ g/mol","2.5 × 10³ g/mol","1.0 × 10⁵ g/mol"],"answer":1,"explanation":"M = wRT/(πV) = 5 × 0.0821 × 300/(0.0123 × 1) = 123.2/0.0123 ≈ 1.0 × 10⁴ g/mol. Osmometry is preferred for polymers because even this tiny π is measurable at room temperature.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-15","question":"Under identical conditions a gas X effuses at half the rate of oxygen. The molar mass of X is:","options":["16 g/mol","128 g/mol","64 g/mol","8 g/mol"],"answer":1,"explanation":"Graham's law: r(X)/r(O₂) = √(32/M) = 1/2, so 32/M = 1/4 and M = 128 g/mol. 64 g/mol forgets to square.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-16","question":"8 g of O₂ and 4 g of H₂ are mixed in a vessel at a total pressure of 1 atm. The partial pressure of O₂ is:","options":["1/9 atm","8/9 atm","2/3 atm","1/2 atm"],"answer":0,"explanation":"n(O₂) = 8/32 = 0.25, n(H₂) = 4/2 = 2, total 2.25 mol. x(O₂) = 0.25/2.25 = 1/9, so p(O₂) = 1/9 atm. Using the mass ratio (2/3) is the trap.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-17","question":"If acetic acid (CH₃COOH, molar mass 60) is completely dimerised in benzene, the molar mass obtained from freezing-point depression would be:","options":["120 g/mol","90 g/mol","30 g/mol","60 g/mol"],"answer":0,"explanation":"Complete association 2A → A₂ gives i = 1/2, so the observed (colligative) molar mass = 60/(1/2) = 120 g/mol, twice the true value.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-solutions-states-18","question":"A 0.1 molal aqueous solution of a weak monobasic acid HA freezes at −0.2046 °C (Kf = 1.86 K kg mol⁻¹). The degree of dissociation of HA is:","options":["1.1%","5%","20%","10%"],"answer":3,"explanation":"i = ΔTf/(Kf·m) = 0.2046/0.186 = 1.1. For HA ⇌ H⁺ + A⁻, i = 1 + α, so α = 0.1 = 10%.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-19","question":"How many of the following statements are correct? (A) For an ideal solution, ΔH(mix) = 0 and ΔV(mix) = 0. (B) Solutions showing large positive deviation from Raoult's law form minimum-boiling azeotropes. (C) Osmotic pressure is preferred over other colligative properties for finding molar masses of proteins. (D) 1 M NaCl and 1 M glucose solutions are isotonic at the same temperature.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"A, B and C are correct. D is wrong: NaCl gives i ≈ 2, so its osmotic pressure is about twice that of 1 M glucose; the solutions are not isotonic.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-20","question":"For CO₂ the van der Waals constants are a = 3.6 atm L² mol⁻² and b = 0.043 L mol⁻¹. Using R = 0.082 L atm K⁻¹ mol⁻¹, its critical temperature is about:","options":["1021 K","302 K","151 K","605 K"],"answer":1,"explanation":"Tc = 8a/(27Rb) = 28.8/(27 × 0.082 × 0.043) = 28.8/0.0952 ≈ 302 K. 1021 K is a/Rb, the Boyle temperature, which is 27/8 times Tc.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-solutions-states-21","question":"Assertion (A): Assuming complete dissociation, 0.1 m aqueous K₄[Fe(CN)₆] and 0.1 m aqueous Al₂(SO₄)₃ have the same freezing point. Reason (R): Each formula unit of both salts gives five ions in solution.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"K₄[Fe(CN)₆] → 4K⁺ + [Fe(CN)₆]⁴⁻ and Al₂(SO₄)₃ → 2Al³⁺ + 3SO₄²⁻: i = 5 for both, so ΔTf = 5 × Kf × 0.1 is the same. R is exactly why A holds.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-solutions-states-22","question":"Match Column I with Column II. (a) Z < 1, (b) Z > 1, (c) Critical temperature, (d) Boyle temperature. (1) The real gas obeys Boyle's law over an appreciable range of pressure; (2) Repulsive forces dominate; (3) Above it the gas cannot be liquefied by pressure alone; (4) Attractive forces dominate.","options":["a-4, b-2, c-1, d-3","a-2, b-4, c-3, d-1","a-2, b-4, c-1, d-3","a-4, b-2, c-3, d-1"],"answer":3,"explanation":"Z < 1 means the gas is more compressible than ideal (attractions win); Z > 1 means repulsion/excluded volume wins. Above Tc no pressure liquefies a gas; at the Boyle temperature Z ≈ 1 over a range of low pressures.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-23","question":"The vapour pressure of water at 293 K is 17.5 mm Hg. 18 g of glucose (molar mass 180) is dissolved in 178.2 g of water. The vapour pressure of the solution is:","options":["17.15 mm Hg","17.5 mm Hg","17.325 mm Hg","15.75 mm Hg"],"answer":2,"explanation":"n(glucose) = 0.1, n(water) = 178.2/18 = 9.9; x(solute) = 0.1/10 = 0.01. Δp = 0.01 × 17.5 = 0.175 mm, so p = 17.5 − 0.175 = 17.325 mm Hg.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-24","question":"Liquids A (p° = 400 mm Hg) and B (p° = 600 mm Hg) form an ideal solution. The vapour in equilibrium with a certain liquid mixture contains equal mole fractions of A and B. The mole fraction of A in the liquid and the total vapour pressure are:","options":["0.6 and 500 mm Hg","0.6 and 480 mm Hg","0.5 and 500 mm Hg","0.4 and 520 mm Hg"],"answer":1,"explanation":"Equal vapour mole fractions need p(A) = p(B): 400x = 600(1 − x), so x(A) = 0.6. Then p(A) = p(B) = 240 mm and total = 480 mm Hg.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-solutions-states-25","question":"For the molecules of an ideal gas at a given temperature, the ratio of the most probable speed : average speed : root-mean-square speed is:","options":["1.224 : 1.128 : 1","1 : 1.128 : 1.224","1 : 1.224 : 1.128","1 : 1 : 1"],"answer":1,"explanation":"u(mp) : u(av) : u(rms) = √(2RT/M) : √(8RT/πM) : √(3RT/M) = √2 : √(8/π) : √3 = 1 : 1.128 : 1.224. The rms speed is always the largest.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-26","question":"The Henry's law constant of a gas in water at 298 K is 50 kbar. If its partial pressure above water is 1 bar, the amount of gas dissolved in 1 kg of water is about:","options":["1.1 mmol","2.0 mmol","0.11 mmol","11 mmol"],"answer":0,"explanation":"x = p/K_H = 1/(50 × 10³) = 2 × 10⁻⁵. 1 kg water = 55.5 mol, so n(gas) ≈ 2 × 10⁻⁵ × 55.5 = 1.11 × 10⁻³ mol ≈ 1.1 mmol. 2.0 mmol would mistake the mole fraction for moles per 100 mol.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-27","question":"A 5% (w/V) solution of cane sugar (molar mass 342) is isotonic with a 0.877% (w/V) solution of a non-electrolyte X at the same temperature. The molar mass of X is about:","options":["180 g/mol","30 g/mol","60 g/mol","120 g/mol"],"answer":2,"explanation":"Isotonic solutions have equal molar concentrations: 5/342 = 0.877/M, so M = 0.877 × 342/5 ≈ 60 g/mol (urea).","difficulty":"very-hard","source":"NEET"},
  {"id":"chem-solutions-states-28","question":"Assuming complete dissociation of electrolytes, which pair of aqueous solutions is isotonic at the same temperature?","options":["0.2 M glucose and 0.1 M K₂SO₄","0.1 M Ca(NO₃)₂ and 0.15 M NaCl","0.1 M urea and 0.1 M NaCl","0.1 M NaCl and 0.1 M Na₂SO₄"],"answer":1,"explanation":"Effective concentrations i·C: Ca(NO₃)₂ 3 × 0.1 = 0.3 and NaCl 2 × 0.15 = 0.3 — equal. The others: 0.1 vs 0.2; 0.2 vs 0.3; 0.2 vs 0.3.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-29","question":"How many of the following statements are correct? (A) In reverse osmosis a pressure larger than the osmotic pressure is applied on the solution side. (B) Red blood cells placed in 0.5% (w/V) NaCl solution shrink. (C) The osmotic pressure of a solution decreases as temperature rises at constant concentration. (D) Cellulose acetate films are used as membranes in reverse-osmosis desalination.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"A and D are correct. B is wrong: 0.5% NaCl is hypotonic to blood (0.9% is isotonic), so water enters and the cells swell. C is wrong: π = CRT increases with T.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-30","question":"1 mol of a gas at 300 K and 10 atm occupies 2.0 L (R = 0.082 L atm K⁻¹ mol⁻¹). Its compressibility factor and the dominant intermolecular effect are:","options":["Z ≈ 0.81; attractive forces dominate","Z ≈ 0.81; repulsive forces dominate","Z ≈ 1.23; attractive forces dominate","Z ≈ 1.23; repulsive forces dominate"],"answer":0,"explanation":"Z = PV/nRT = (10 × 2.0)/(1 × 0.082 × 300) = 20/24.6 ≈ 0.81. Z < 1 means the gas is more compressible than ideal, so attractions dominate.","difficulty":"very-hard","source":"JEE Main"},
  {"id": "chem-solutions-states-31", "question": "Which of the following concentration terms does NOT change with temperature?", "options": ["Molarity", "Molality", "Mass by volume percentage", "Normality"], "answer": 1, "explanation": "Molality is moles of solute per kilogram of solvent, built only from masses, so it is independent of temperature. Molarity, normality and w/V % use the solution's volume, which changes as the liquid expands.", "difficulty": "easy", "source": "JEE Main · NEET"},
  {"id": "chem-solutions-states-32", "question": "A gas collected over water has a total pressure of 760 mm Hg at a temperature where the aqueous tension is 24 mm Hg. The pressure of the dry gas is:", "options": ["24 mm Hg", "784 mm Hg", "736 mm Hg", "760 mm Hg"], "answer": 2, "explanation": "By Dalton's law, p(dry gas) = p(total) − aqueous tension = 760 − 24 = 736 mm Hg.", "difficulty": "easy", "source": "JEE Main · NEET"},
  {"id": "chem-solutions-states-33", "question": "Which colligative property is preferred for finding the molar masses of proteins and polymers?", "options": ["Osmotic pressure", "Elevation of boiling point", "Depression of freezing point", "Relative lowering of vapour pressure"], "answer": 0, "explanation": "Osmotic pressure is large enough to measure even for very dilute solutions of macromolecules and is measured at room temperature, so biomolecules are not denatured. ΔTb and ΔTf would be far too small to read accurately.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "chem-solutions-states-35", "question": "The molality of a 10% (w/w) aqueous solution of NaOH (molar mass 40 g/mol) is about:", "options": ["2.78 m", "4.00 m", "0.25 m", "2.50 m"], "answer": 0, "explanation": "100 g of solution has 10 g NaOH (0.25 mol) in 90 g water. Molality = 0.25/0.090 = 2.78 m. 2.50 m wrongly uses 100 g of solution as the solvent mass.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-solutions-states-36", "question": "The molal elevation constant (Kb) of a liquid depends on:", "options": ["The nature of the solvent only", "The nature of the solute only", "The degree of dissociation of the solute", "The concentration of the solution"], "answer": 0, "explanation": "Kb = R·Tb²·M(solvent)/(1000·ΔvapH) contains only properties of the solvent (its boiling point, molar mass and enthalpy of vaporisation). The solute affects ΔTb only through its molality and van 't Hoff factor.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-solutions-states-37", "question": "The total translational kinetic energy of 1 mol of an ideal gas at 300 K is about (R = 8.314 J K⁻¹ mol⁻¹):", "options": ["2.49 kJ", "7.48 kJ", "1.25 kJ", "3.74 kJ"], "answer": 3, "explanation": "E = (3/2)RT = 1.5 × 8.314 × 300 = 3741 J ≈ 3.74 kJ. 2.49 kJ is RT alone.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-solutions-states-38", "question": "A sealed steel cylinder contains a gas at 2.0 atm and 27 °C. If it is heated to 127 °C, the pressure becomes about:", "options": ["1.5 atm", "9.4 atm", "2.67 atm", "2.0 atm"], "answer": 2, "explanation": "At constant volume P ∝ T (kelvin): P₂ = 2.0 × 400/300 = 2.67 atm. Using Celsius temperatures (127/27) gives the wrong 9.4 atm.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-solutions-states-39", "question": "Which mixture forms a maximum-boiling azeotrope?", "options": ["Nitric acid (about 68%) + water", "Benzene + toluene", "n-Hexane + n-heptane", "Ethanol + water"], "answer": 0, "explanation": "HNO₃ and water show a large negative deviation from Raoult's law (strong attraction between unlike molecules), giving a maximum-boiling azeotrope at about 68% HNO₃ (393.5 K). Ethanol–water gives a minimum-boiling azeotrope; the other two pairs are nearly ideal.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "chem-solutions-states-40", "question": "A gas has a density of 2.6 g/L at 27 °C and 2.0 atm. Its molar mass is about (R = 0.0821 L atm K⁻¹ mol⁻¹):", "options": ["64 g/mol", "32 g/mol", "16 g/mol", "44 g/mol"], "answer": 1, "explanation": "From PM = dRT: M = dRT/P = 2.6 × 0.0821 × 300/2.0 = 32.0 g/mol. Forgetting to divide by 2 atm gives 64.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-solutions-states-41", "question": "A 2.0 L flask of N₂ at 3.0 atm is connected through a tap to a 3.0 L flask of O₂ at 2.0 atm at the same temperature. After the tap is opened, the total pressure is:", "options": ["2.4 atm", "5.0 atm", "1.2 atm", "2.5 atm"], "answer": 0, "explanation": "Each gas expands into 5.0 L: p(N₂) = 3 × 2/5 = 1.2 atm, p(O₂) = 2 × 3/5 = 1.2 atm. Total = 2.4 atm. 2.5 atm is the simple average of the two pressures, which ignores the volumes.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-solutions-states-42", "question": "10 g of a non-volatile, non-electrolyte solute dissolved in 90 g of water lowers the vapour pressure by 2%. Using the dilute-solution approximation, the molar mass of the solute is:", "options": ["50 g/mol", "20 g/mol", "100 g/mol", "180 g/mol"], "answer": 2, "explanation": "Δp/p° ≈ n(solute)/n(water): 0.02 = (10/M)/(90/18) = (10/M)/5, so 10/M = 0.1 and M = 100 g/mol.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-solutions-states-43", "question": "The van 't Hoff factor of K₃[Fe(CN)₆] that is 80% dissociated in water is:", "options": ["3.2", "2.6", "3.4", "4.0"], "answer": 2, "explanation": "K₃[Fe(CN)₆] → 3K⁺ + [Fe(CN)₆]³⁻ gives n = 4 ions. i = 1 + (n − 1)α = 1 + 3 × 0.8 = 3.4. 4.0 would need complete dissociation.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-solutions-states-44", "question": "Cotton plugs soaked in aqueous NH₃ and conc. HCl are placed at the two ends of a 100 cm glass tube. The white ring of NH₄Cl first forms at about (NH₃ = 17, HCl = 36.5):", "options": ["59 cm from the NH₃ end", "41 cm from the NH₃ end", "50 cm from either end", "68 cm from the HCl end"], "answer": 0, "explanation": "r(NH₃)/r(HCl) = √(36.5/17) = 1.465. In the same time the distances are in this ratio, so the NH₃ side covers 100 × 1.465/2.465 ≈ 59.4 cm. The lighter gas travels farther, so the ring is nearer the HCl end.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-solutions-states-45", "question": "At what temperature will the root-mean-square speed of SO₂ molecules equal that of O₂ molecules at 27 °C?", "options": ["150 °C", "600 °C", "327 °C", "54 °C"], "answer": 2, "explanation": "u(rms) ∝ √(T/M), so T/M must be equal: T(SO₂) = 300 K × 64/32 = 600 K = 327 °C. 600 °C confuses kelvin with Celsius.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-solutions-states-46", "question": "For an ideal binary solution of A and B, the total vapour pressure (in mm Hg) varies with the mole fraction of B in the liquid as P = 120 − 75x(B). The vapour pressures of pure A and pure B are:", "options": ["p°A = 120, p°B = 75", "p°A = 120, p°B = 45", "p°A = 45, p°B = 120", "p°A = 75, p°B = 120"], "answer": 1, "explanation": "For an ideal solution P = p°A + (p°B − p°A)x(B). Comparing: p°A = 120 and p°B − p°A = −75, so p°B = 45 mm Hg. The slope (75) is not itself a vapour pressure.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-solutions-states-47", "question": "Assuming complete dissociation, the osmotic pressure of 0.01 M aqueous CaCl₂ at 27 °C is about (R = 0.0821 L atm K⁻¹ mol⁻¹):", "options": ["0.25 atm", "0.49 atm", "0.022 atm", "0.74 atm"], "answer": 3, "explanation": "π = iCRT with i = 3 (Ca²⁺ + 2Cl⁻): π = 3 × 0.01 × 0.0821 × 300 = 0.739 atm. Ignoring dissociation gives 0.25 atm.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-solutions-states-48", "question": "1.0 g of a non-electrolyte (molar mass 200 g/mol) dissolved in 50 g of a solvent lowers its freezing point by 0.50 K. The cryoscopic constant of the solvent is:", "options": ["5.0 K kg mol⁻¹", "1.0 K kg mol⁻¹", "10 K kg mol⁻¹", "2.5 K kg mol⁻¹"], "answer": 0, "explanation": "Molality = (1.0/200)/0.050 = 0.10 mol/kg. Kf = ΔTf/m = 0.50/0.10 = 5.0 K kg mol⁻¹.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-solutions-states-49", "question": "For a van der Waals gas, how many of the following relations are correct? (A) Tc = 8a/(27Rb). (B) Vc = 3b. (C) Pc = a/(27b²). (D) Boyle temperature T(B) = a/(Rb).", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are standard results from the van der Waals equation (Tc, Vc, Pc from the critical point; T(B) = a/Rb). The inversion temperature, 2a/(Rb), is twice the Boyle temperature.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-solutions-states-50", "question": "At very high pressure, the van der Waals equation for 1 mol of a gas reduces to:", "options": ["PV = RT − a/V", "PV = RT + Pb", "PV = RT", "PV = RT + a/V"], "answer": 1, "explanation": "At high pressure V is small, so b cannot be neglected, while a/V² becomes small compared with the large P. Then P(V − b) = RT, i.e. PV = RT + Pb and Z = 1 + Pb/RT > 1. PV = RT − a/V is the low-pressure form.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-solutions-states-51", "question": "Assertion (A): Osmotic pressure is the preferred colligative property for finding the molar mass of proteins. Reason (R): Osmotic pressure can be measured only at high temperatures, at which proteins are stable.", "options": ["Both A and R are true, and R explains A", "Both A and R are true, but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true: even dilute protein solutions give a measurable osmotic pressure. R is false: the measurement is made around room temperature, which is an advantage because proteins denature at high temperatures.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "chem-solutions-states-52", "question": "100 mL of 0.2 M NaCl is mixed with 100 mL of 0.1 M glucose. Assuming complete dissociation of NaCl, the osmotic pressure of the mixture at 300 K is about (R = 0.0821 L atm K⁻¹ mol⁻¹):", "options": ["6.16 atm", "4.93 atm", "3.69 atm", "7.39 atm"], "answer": 0, "explanation": "Particles: NaCl 0.02 mol × 2 = 0.04 mol, glucose 0.01 mol; total 0.05 mol in 0.200 L = 0.25 M. π = 0.25 × 0.0821 × 300 = 6.16 atm. Forgetting the dilution to 200 mL or the factor 2 for NaCl gives the other values.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-solutions-states-53", "question": "A and B form an ideal solution. At the temperature where p°A = 1000 mm Hg and p°B = 400 mm Hg, a liquid mixture of A and B boils under 760 mm Hg. The mole fraction of A in the first vapour formed is about:", "options": ["0.60", "0.79", "0.40", "0.66"], "answer": 1, "explanation": "Boiling means total pressure = 760: 400 + (1000 − 400)x(A) = 760, so x(A) = 0.6 in the liquid. In the vapour y(A) = 0.6 × 1000/760 = 0.79. 0.60 is the liquid composition, not the vapour.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-solutions-states-54", "question": "Match the quantity (Column I) with its unit (Column II). (a) Cryoscopic constant Kf, (b) Henry's law constant K_H in p = K_H·x, (c) van der Waals constant a, (d) van der Waals constant b. (1) L mol⁻¹, (2) K kg mol⁻¹, (3) bar, (4) atm L² mol⁻².", "options": ["a-2, b-4, c-3, d-1", "a-3, b-2, c-4, d-1", "a-2, b-3, c-1, d-4", "a-2, b-3, c-4, d-1"], "answer": 3, "explanation": "Kf = ΔTf/m has K kg mol⁻¹. K_H = p/x has pressure units (bar), since x is dimensionless. a/V² is a pressure, so a is atm L² mol⁻²; b is a volume per mole, L mol⁻¹.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-solutions-states-55", "question": "A salt AB₂ (giving A²⁺ and B⁻) is 50% dissociated in water. The freezing point of its 0.2 molal solution is (Kf = 1.86 K kg mol⁻¹):", "options": ["−0.744 °C", "−0.558 °C", "−1.116 °C", "−0.372 °C"], "answer": 0, "explanation": "AB₂ → A²⁺ + 2B⁻, so i = 1 + 2α = 1 + 2 × 0.5 = 2.0. ΔTf = 2.0 × 1.86 × 0.2 = 0.744 K, so the solution freezes at −0.744 °C. −1.116 °C assumes complete dissociation (i = 3).", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-solutions-states-56", "question": "Phenol forms dimers in benzene. 0.94 g of phenol (molar mass 94) in 50 g of benzene lowers the freezing point by 0.614 K (Kf of benzene = 5.12 K kg mol⁻¹). The percentage of phenol molecules that are dimerised is about:", "options": ["60%", "80%", "40%", "100%"], "answer": 1, "explanation": "Expected ΔTf = 5.12 × (0.01/0.050) = 1.024 K, so i = 0.614/1.024 = 0.60. For 2PhOH ⇌ (PhOH)₂, i = 1 − α/2, so α = 2(1 − 0.60) = 0.80, i.e. 80%. 60% is i itself, not α.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-solutions-states-57", "question": "How many of the following statements are correct? (A) Real gases deviate most from ideal behaviour at low temperature and high pressure. (B) The van der Waals constant b is about four times the actual volume of the molecules in 1 mol of gas. (C) A gas above its critical temperature cannot be liquefied by pressure alone. (D) All gases cool when they undergo Joule–Thomson expansion at room temperature.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, B and C are correct. D is wrong: H₂ and He are above their inversion temperatures at room temperature, so they warm on Joule–Thomson expansion and must be pre-cooled before liquefaction.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-solutions-states-58", "question": "An equimolar mixture of helium and methane is allowed to effuse through a pinhole. The mole fraction of helium in the gas that first escapes is about:", "options": ["0.50", "0.67", "0.33", "0.80"], "answer": 1, "explanation": "Rate ∝ (partial pressure)/√M. With equal partial pressures, r(He)/r(CH₄) = √(16/4) = 2, so the effused gas has He : CH₄ = 2 : 1, i.e. x(He) = 2/3 ≈ 0.67.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-solutions-states-59", "question": "Liquids A and B form an ideal solution. A mixture of 1 mol A and 1 mol B has a vapour pressure of 500 mm Hg. When 2 mol more of A is added, the vapour pressure becomes 450 mm Hg at the same temperature. The vapour pressures of pure A and pure B are:", "options": ["400 and 600 mm Hg", "300 and 700 mm Hg", "500 and 500 mm Hg", "600 and 400 mm Hg"], "answer": 0, "explanation": "0.5p°A + 0.5p°B = 500, so p°A + p°B = 1000. With 3 mol A and 1 mol B: 0.75p°A + 0.25p°B = 450, so 3p°A + p°B = 1800. Subtracting: 2p°A = 800, p°A = 400 and p°B = 600 mm Hg. Adding A lowered the pressure, so A must be the less volatile liquid.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-solutions-states-60", "question": "0.1 mol of Al₂(SO₄)₃ is dissolved in 891 g of water at a temperature where the vapour pressure of water is 24.0 mm Hg. Assuming complete dissociation, the vapour pressure of the solution is:", "options": ["22.80 mm Hg", "23.76 mm Hg", "23.52 mm Hg", "23.95 mm Hg"], "answer": 1, "explanation": "Al₂(SO₄)₃ gives 5 ions: 0.5 mol of particles. Water = 891/18 = 49.5 mol. Mole fraction of solute particles = 0.5/(49.5 + 0.5) = 0.01, so p = 24.0 × 0.99 = 23.76 mm Hg. 23.95 mm Hg ignores dissociation.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id":"chem-solutions-states-61","question":"Assuming complete dissociation of electrolytes, which aqueous solution has the highest boiling point?","options":["0.1 m NaCl","0.05 m CaCl₂","0.1 m glucose","0.1 m urea"],"answer":0,"explanation":"ΔTb = i·Kb·m: glucose and urea 0.1, CaCl₂ 3 × 0.05 = 0.15, NaCl 2 × 0.1 = 0.2. NaCl gives the most particles. CaCl₂ is the trap, since it has the larger i but only half the molality.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"chem-solutions-states-62","question":"The absolute temperature of a fixed amount of an ideal gas is doubled while its pressure is halved. Its volume becomes:","options":["unchanged","four times the original","half the original","twice the original"],"answer":1,"explanation":"V = nRT/P, so V ∝ T/P = 2/(1/2) = 4 times the original. Treating the two changes as cancelling gives 'unchanged'.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"chem-solutions-states-63","question":"Raoult's law for a volatile component (p = p°x) can be seen as a special case of Henry's law (p = K_H·x) in which:","options":["K_H equals the total pressure of the solution","K_H equals zero","K_H equals the vapour pressure of the pure component, p°","K_H equals 1/p°"],"answer":2,"explanation":"Both laws state that the partial pressure of a component is proportional to its mole fraction in the liquid. When the proportionality constant K_H becomes the pure-component vapour pressure p°, Henry's law reduces to Raoult's law.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"chem-solutions-states-64","question":"Physiological saline is 0.9% (w/V) NaCl. Assuming complete dissociation, its osmotic pressure at body temperature (37 °C) is about (R = 0.0821 L atm K⁻¹ mol⁻¹):","options":["3.92 atm","0.25 atm","7.53 atm","7.83 atm"],"answer":3,"explanation":"9 g/L ÷ 58.5 = 0.154 M; with i = 2 the particle concentration is 0.308 M. π = iCRT = 0.308 × 0.0821 × 310 = 7.83 atm. Forgetting i gives 3.92 atm, and using 298 K instead of 310 K gives 7.53 atm.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "chem-solutions-states-65", "question": "Using the van der Waals equation, the pressure exerted by 1 mol of NH₃ in a 1.0 L vessel at 300 K is about (a = 4.17 atm L² mol⁻², b = 0.0371 L mol⁻¹, R = 0.0821 L atm K⁻¹ mol⁻¹):", "options": ["24.6 atm", "29.4 atm", "21.4 atm", "25.6 atm"], "answer": 2, "explanation": "P = RT/(V − b) − a/V² = 24.63/0.9629 − 4.17 = 25.58 − 4.17 = 21.4 atm, below the ideal 24.6 atm because the strong attraction (large a) dominates. 25.6 atm includes only the volume correction.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id":"chem-solutions-states-66","question":"When the temperature of a gas is raised, its Maxwell–Boltzmann distribution of molecular speeds changes so that:","options":["the most probable speed increases, the peak becomes lower and broader, and the area under the curve stays the same","the most probable speed decreases and the peak becomes taller","the most probable speed increases and the area under the curve increases","all molecules acquire the same higher speed"],"answer":0,"explanation":"u_mp = √(2RT/M) rises with T, so the curve shifts right; because the total number of molecules (the area) is fixed, the curve flattens and broadens. The area is the number of molecules, so it cannot increase.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"chem-solutions-states-67","question":"Using Kb = RTb²M/(1000 ΔvapH), with M in g/mol, the ebullioscopic constant of water (Tb = 373 K, ΔvapH = 40.66 kJ/mol, R = 8.314 J K⁻¹ mol⁻¹) is about:","options":["1.86 K kg mol⁻¹","0.512 K kg mol⁻¹","5.12 K kg mol⁻¹","0.0512 K kg mol⁻¹"],"answer":1,"explanation":"Kb = 8.314 × 373² × 18/(1000 × 40 660) = 0.512 K kg mol⁻¹. Kb depends only on the solvent (its boiling point, molar mass and enthalpy of vaporisation); 1.86 is the cryoscopic constant of water.","difficulty":"hard","source":"JEE Advanced pattern"},
  {"id":"chem-solutions-states-68","question":"A 0.01 molal aqueous solution of the complex CoCl₃·5NH₃ freezes at −0.0558 °C (Kf = 1.86 K kg mol⁻¹; assume complete ionisation). The complex is:","options":["[Co(NH₃)₅Cl₃]","[Co(NH₃)₅]Cl₃","[Co(NH₃)₅Cl]Cl₂","[Co(NH₃)₄Cl₂]Cl·NH₃"],"answer":2,"explanation":"i = ΔTf/(Kf·m) = 0.0558/(1.86 × 0.01) = 3, so each unit gives 3 ions: [Co(NH₃)₅Cl]²⁺ + 2Cl⁻. The coordination number 6 is satisfied by 5 NH₃ + 1 Cl; [Co(NH₃)₅]Cl₃ would give i = 4.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"chem-solutions-states-69","question":"An open flask containing air is heated from 27 °C to 477 °C at constant pressure. The fraction of the air originally present that is expelled is:","options":["0.4","0.94","0.75","0.6"],"answer":3,"explanation":"At constant P and V, n ∝ 1/T: n₂/n₁ = 300/750 = 0.4, so 0.6 of the air leaves. 0.4 is the fraction remaining; using Celsius temperatures (27/477) gives 0.94.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "chem-solutions-states-70", "question": "At 273 K and 100 atm, a gas whose intermolecular attraction can be neglected (a ≈ 0) has b = 0.0244 L mol⁻¹. Its compressibility factor is about (R = 0.0821 L atm K⁻¹ mol⁻¹):", "options": ["0.891", "1.000", "1.244", "1.109"], "answer": 3, "explanation": "With a = 0 the van der Waals equation gives P(V − b) = RT, so Z = PV/RT = 1 + Pb/RT = 1 + (100 × 0.0244)/(0.0821 × 273) = 1.109. Z > 1 because the finite molecular volume (repulsion) dominates, as for H₂ and He.", "difficulty": "hard", "source": "JEE Advanced pattern"},
  {"id":"chem-solutions-states-71","question":"Liquids A (p° = 300 mm Hg) and B (p° = 100 mm Hg) form an ideal solution. The vapour above an equimolar liquid mixture is completely condensed, and the condensate is allowed to reach equilibrium with its own vapour. The mole fraction of A in this second vapour is:","options":["0.90","0.75","0.50","0.83"],"answer":0,"explanation":"First vapour: y_A = (0.5 × 300)/(0.5 × 300 + 0.5 × 100) = 0.75. The condensate (x_A = 0.75) gives P = 225 + 25 = 250 mm Hg and y_A = 225/250 = 0.90. Each evaporation–condensation step enriches the more volatile component; this is the principle of fractional distillation.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-solutions-states-72","question":"0.1 M aqueous NaCl and 0.15 M aqueous glucose are separated by a semipermeable membrane at the same temperature. Assuming complete dissociation of NaCl, water will:","options":["flow from the NaCl solution into the glucose solution","flow from the glucose solution into the NaCl solution","not flow, since the solutions are isotonic","flow in both directions at equal rates only if the temperature is 0 °C"],"answer":1,"explanation":"Effective particle concentrations: NaCl 2 × 0.1 = 0.20 M, glucose 0.15 M. Water moves towards the higher osmotic pressure, i.e. into the NaCl solution. Comparing molarities alone (0.1 < 0.15) predicts the opposite.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-solutions-states-73","question":"A benzene solution is 0.1 molal in acetic acid (completely dimerised in benzene) and also 0.1 molal in naphthalene. Its freezing point depression is (Kf of benzene = 5.12 K kg mol⁻¹):","options":["1.024 K","0.512 K","0.768 K","0.256 K"],"answer":2,"explanation":"Colligative effects add: dimerisation halves the acetic acid particles to 0.05 m, and naphthalene adds 0.1 m. ΔTf = 5.12 × 0.15 = 0.768 K. Ignoring the dimerisation gives 1.024 K.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "chem-solutions-states-74", "question": "How many of the following statements are correct? (A) Solutions showing large positive deviation from Raoult's law form minimum-boiling azeotropes. (B) Ethanol and water form a minimum-boiling azeotrope at about 95.6% (by mass) ethanol. (C) Nitric acid and water form a maximum-boiling azeotrope at about 68% (by mass) HNO₃. (D) An azeotropic mixture can be separated into its pure components by fractional distillation.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, B and C are correct. D is false: an azeotrope boils at constant temperature with vapour of the same composition as the liquid, so fractional distillation cannot separate it (that is why absolute alcohol needs other methods). Three are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"chem-solutions-states-75","question":"Air (20% O₂, 80% N₂ by volume) is in equilibrium with water at 298 K. Given Henry's law constants K_H(O₂) = 34.86 kbar and K_H(N₂) = 76.48 kbar (p = K_H·x), the ratio of moles of O₂ to moles of N₂ dissolved in the water is about:","options":["0.25","0.11","1.10","0.55"],"answer":3,"explanation":"x = p/K_H, so x(O₂)/x(N₂) = (0.2/34.86)/(0.8/76.48) = 0.00574/0.01046 = 0.55. Dissolved air is richer in O₂ (35% O₂) than atmospheric air (ratio 0.25) because O₂ has the smaller K_H, i.e. is more soluble.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-solutions-states-76","question":"Equal masses of H₂ and O₂ are placed in a container at the same temperature. The ratio of the total translational kinetic energy of the H₂ molecules to that of the O₂ molecules is:","options":["16 : 1","1 : 1","4 : 1","1 : 16"],"answer":0,"explanation":"The average kinetic energy per molecule (3/2 kT) is the same for both gases, so the total is proportional to the number of molecules. Equal masses give n(H₂)/n(O₂) = 32/2 = 16. 1 : 1 is the per-molecule ratio and 4 : 1 is the ratio of rms speeds.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-solutions-states-77","question":"Match each liquid pair (Column I) with its description (Column II). (a) n-Hexane + n-heptane, (b) Ethanol + acetone, (c) Chloroform + acetone, (d) Nitric acid + water. (1) Forms a maximum-boiling azeotrope at about 68% acid; (2) Nearly ideal, ΔH(mix) ≈ 0; (3) Negative deviation caused by C–H···O=C hydrogen bonding between the components; (4) Positive deviation, ΔV(mix) > 0.","options":["a-2, b-3, c-4, d-1","a-2, b-4, c-3, d-1","a-4, b-2, c-3, d-1","a-2, b-4, c-1, d-3"],"answer":1,"explanation":"Hexane–heptane have almost identical interactions (ideal). Acetone breaks up the hydrogen bonding of ethanol, so the mixture expands and shows positive deviation. Chloroform's C–H bonds hydrogen-bond to acetone's C=O (negative deviation). HNO₃–water gives the classic maximum-boiling azeotrope at about 68%. So a-2, b-4, c-3, d-1.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-solutions-states-78","question":"1.0 g of a polymer is dissolved in water to give 100 mL of solution. At 300 K the solution supports an osmotic column of 3.0 cm of liquid (density 1.0 g/mL) above the solvent level. Taking g = 10 m/s² and R = 8.314 J K⁻¹ mol⁻¹, the molar mass of the polymer is about:","options":["8.3 × 10⁵ g/mol","8.3 × 10³ g/mol","8.3 × 10⁴ g/mol","2.5 × 10⁵ g/mol"],"answer":2,"explanation":"π = hρg = 0.030 × 1000 × 10 = 300 Pa. c = π/RT = 300/(8.314 × 300) = 0.120 mol/m³ = 1.20 × 10⁻⁴ mol/L. The concentration is 10 g/L, so M = 10/(1.20 × 10⁻⁴) = 8.3 × 10⁴ g/mol. Using 1.0 g per litre instead of per 100 mL gives 8.3 × 10³.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-solutions-states-79","question":"Andrews found the critical temperature of CO₂ to be 31.1 °C. Which of the following gases CANNOT be liquefied at 27 °C however high the pressure applied?","options":["CO₂","NH₃","SO₂","N₂"],"answer":3,"explanation":"A gas can be liquefied by pressure alone only below its critical temperature. CO₂ (Tc 304 K), NH₃ (405 K) and SO₂ (431 K) all have Tc above 300 K, but N₂ (Tc 126 K) must first be cooled. CO₂ is the trap: 27 °C is just below its Tc of 31.1 °C.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-solutions-states-80","question":"A gaseous mixture of helium and methane has an average molar mass of 10 g/mol. The percentage by MASS of helium in the mixture is:","options":["20%","50%","80%","40%"],"answer":0,"explanation":"4x + 16(1 − x) = 10 gives mole fraction of He x = 0.5. In 1 mol of mixture (10 g), He contributes 0.5 × 4 = 2 g, i.e. 20% by mass. 50% is the mole (volume) percentage.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-solutions-states-81","question":"A solution of 0.5 mol of glucose in 1.00 kg of water is cooled to −2.79 °C, and the ice that separates is removed (Kf = 1.86 K kg mol⁻¹). The mass of ice separated is about:","options":["333 g","667 g","500 g","930 g"],"answer":1,"explanation":"At −2.79 °C the remaining solution must have m = 2.79/1.86 = 1.5 mol/kg. With 0.5 mol of glucose that needs 0.5/1.5 = 0.333 kg of water, so 1000 − 333 = 667 g of water froze out as pure ice. 333 g is the water left, not the ice.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-solutions-states-82","question":"The relative lowering of vapour pressure of an aqueous solution of a non-volatile non-electrolyte is 0.01. The elevation of its boiling point is about (Kb of water = 0.52 K kg mol⁻¹):","options":["0.052 K","0.52 K","0.29 K","2.9 K"],"answer":2,"explanation":"Δp/p° = x(solute) = 0.01, so per 0.99 mol water (17.8 g) there is 0.01 mol solute: m = 0.01/0.99 × 1000/18 = 0.56 mol/kg. ΔTb = 0.52 × 0.56 = 0.29 K. Treating 0.01 itself as the molality gives only 0.0052 K.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-solutions-states-83","question":"A 2.0 L vessel contains an ideal gas at 1.0 atm. The total translational kinetic energy of all the gas molecules is about (1 atm = 101 325 Pa):","options":["203 J","It cannot be found without knowing the gas and its temperature","507 J","304 J"],"answer":3,"explanation":"Total translational KE = (3/2)nRT = (3/2)PV = 1.5 × 101 325 × 2.0 × 10⁻³ = 304 J. It depends only on P and V, not on the identity of the gas or the temperature separately. 203 J is PV itself.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-solutions-states-84","question":"O₂ molecules at absolute temperature T have rms speed u. When the temperature is doubled, the gas dissociates completely into O atoms. The rms speed of the atoms is:","options":["2u","u/√2","4u","√2 u"],"answer":0,"explanation":"u_rms = √(3RT/M). Doubling T multiplies it by √2, and halving the molar mass (32 → 16) multiplies it by another √2, giving 2u. Considering only the temperature change gives √2 u.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "chem-solutions-states-85", "question": "Aniline (molar mass 93) is steam-distilled at 1 atm; the mixture boils at about 98.5 °C, where the vapour pressures are p°(water) = 717 mm Hg and p°(aniline) = 43 mm Hg. The mass ratio of aniline to water in the distillate is about:", "options": ["0.06", "0.31", "3.2", "0.50"], "answer": 1, "explanation": "For immiscible liquids each exerts its full vapour pressure, so moles in the vapour are in the ratio of the pressures: m(aniline)/m(water) = (43 × 93)/(717 × 18) = 3999/12 906 = 0.31. Using the pressure ratio alone (43/717) gives 0.06 and ignores aniline's much larger molar mass.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"chem-solutions-states-86","question":"Which of the following is NOT a colligative property of a dilute solution?","options":["Osmotic pressure","Viscosity","Relative lowering of vapour pressure","Elevation of boiling point"],"answer":1,"explanation":"Colligative properties depend only on the number of solute particles, not their nature. Osmotic pressure, relative lowering of vapour pressure, boiling-point elevation and freezing-point depression are colligative; viscosity depends strongly on the nature of the solute and solvent.","difficulty":"easy","source":"NEET"},
  {"id":"chem-solutions-states-87","question":"An air bubble released at the bottom of a lake grows larger as it rises (temperature roughly constant). The gas law that best explains this is:","options":["Boyle's law","Graham's law","Avogadro's law","Charles's law"],"answer":0,"explanation":"As the bubble rises the surrounding pressure falls; at constant temperature and amount of gas, PV = constant (Boyle's law), so the volume increases.","difficulty":"easy","source":"NEET"},
  {"id":"chem-solutions-states-88","question":"The freezing-point depression of a 0.2 molal aqueous urea solution is (Kf of water = 1.86 K kg mol⁻¹):","options":["9.3 K","0.186 K","0.744 K","0.372 K"],"answer":3,"explanation":"Urea is a non-electrolyte (i = 1), so ΔTf = iKf·m = 1.86 × 0.2 = 0.372 K. 9.3 K comes from dividing instead of multiplying.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-solutions-states-89","question":"A 0.1 molal aqueous K₂SO₄ solution is completely dissociated. Its boiling-point elevation is (Kb of water = 0.52 K kg mol⁻¹):","options":["0.052 K","0.104 K","0.156 K","0.208 K"],"answer":2,"explanation":"K₂SO₄ → 2K⁺ + SO₄²⁻ gives i = 3. ΔTb = iKb·m = 3 × 0.52 × 0.1 = 0.156 K. Taking i = 1 gives 0.052 K.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-solutions-states-90","question":"A vessel contains 4 g of H₂, 32 g of O₂ and 28 g of N₂ at a total pressure of 4 atm. The partial pressure of H₂ is:","options":["0.25 atm","2 atm","1.33 atm","1 atm"],"answer":1,"explanation":"Moles: H₂ = 2, O₂ = 1, N₂ = 1; total 4 mol. x(H₂) = 0.5, so p(H₂) = 0.5 × 4 = 2 atm (Dalton's law). Using mass fractions (4/64) gives 0.25 atm.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-solutions-states-91","question":"Equal volumes of SO₂ and O₂ effuse through the same pinhole under identical conditions. The ratio of the time taken by SO₂ to that taken by O₂ is:","options":["1.41","0.50","0.71","2.00"],"answer":0,"explanation":"Rate ∝ 1/√M, so time for equal volumes ∝ √M. t(SO₂)/t(O₂) = √(64/32) = √2 = 1.41. 0.71 is the rate ratio, and 2.00 forgets the square root.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-92","question":"For the formation of an ideal solution from its pure liquid components at constant T and P, which mixing quantity is NOT zero?","options":["ΔmixH","ΔmixV","ΔmixU","ΔmixG"],"answer":3,"explanation":"For an ideal solution ΔmixH = 0 and ΔmixV = 0 because A–B interactions equal the average of A–A and B–B interactions. Mixing still increases entropy (ΔmixS > 0), so ΔmixG = ΔmixH − TΔmixS is negative, which is why mixing is spontaneous.","difficulty":"moderate","source":"JEE Main"},
  {"id":"chem-solutions-states-93","question":"Liquids A (p°A = 400 mm Hg) and B (p°B = 200 mm Hg) form an ideal solution. The mole fraction of A in the liquid that is in equilibrium with a vapour containing equal moles of A and B is:","options":["2/3","1/4","1/3","1/2"],"answer":2,"explanation":"y(A) = 400x/(400x + 200(1 − x)) = 0.5 gives 400x = 200(1 − x), so x = 1/3. The vapour is always richer in the more volatile component, so the liquid must contain less A than the vapour.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-solutions-states-94","question":"1.8 g of a non-volatile non-electrolyte dissolved in 100 g of benzene lowers its freezing point by 0.512 K (Kf of benzene = 5.12 K kg mol⁻¹). The molar mass of the solute is:","options":["1800 g/mol","180 g/mol","18 g/mol","90 g/mol"],"answer":1,"explanation":"Molality = ΔTf/Kf = 0.512/5.12 = 0.1 mol kg⁻¹, so moles in 0.100 kg = 0.01 mol and M = 1.8/0.01 = 180 g/mol. Forgetting to convert 100 g to kg gives 1800.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-solutions-states-95","question":"Benzoic acid (molar mass 122) dimerises in benzene. Its molar mass determined by freezing-point depression is 203.3 g/mol. The percentage of benzoic acid molecules associated into dimers is about:","options":["80%","60%","40%","20%"],"answer":0,"explanation":"i = normal M/observed M = 122/203.3 = 0.60. For 2A ⇌ A₂, i = 1 − α/2, so α = 2(1 − 0.60) = 0.80, i.e. 80%. 60% is the van 't Hoff factor read as a percentage.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-solutions-states-96","question":"The osmotic pressure at 300 K of a 0.1 M CaCl₂ solution that is 80% dissociated is about (R = 0.0821 L atm K⁻¹ mol⁻¹):","options":["2.5 atm","4.4 atm","7.4 atm","6.4 atm"],"answer":3,"explanation":"CaCl₂ → Ca²⁺ + 2Cl⁻; i = 1 + (3 − 1)(0.8) = 2.6. π = iCRT = 2.6 × 0.1 × 0.0821 × 300 = 6.4 atm. Complete dissociation (i = 3) gives 7.4 atm.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-97","question":"A solution of urea containing 6 g per litre (molar mass 60) is isotonic at the same temperature with a solution of K₄[Fe(CN)₆] that is 90% dissociated. The molarity of the K₄[Fe(CN)₆] solution is about:","options":["0.10 M","0.020 M","0.022 M","0.025 M"],"answer":2,"explanation":"Urea = 0.1 M (i = 1). For K₄[Fe(CN)₆] → 4K⁺ + [Fe(CN)₆]⁴⁻, i = 1 + 4(0.9) = 4.6. Isotonic means iC equal: C = 0.1/4.6 = 0.022 M. Full dissociation (i = 5) gives 0.020 M.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-solutions-states-98","question":"1 mol of a gas confined to 0.200 L at 300 K exerts a pressure of 100 atm (R = 0.0821 L atm K⁻¹ mol⁻¹). Which statement is correct?","options":["Z ≈ 1.23, so repulsive forces dominate","Z ≈ 0.81, so attractive forces dominate under these conditions","Z ≈ 0.81, so repulsive forces dominate","Z = 1, so the gas behaves ideally"],"answer":1,"explanation":"Z = PV/nRT = 100 × 0.200/(0.0821 × 300) = 0.81. Z < 1 means the gas is more compressible than an ideal gas, which happens when intermolecular attractions dominate. Z > 1 would indicate repulsions (excluded volume) dominate.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-solutions-states-99","question":"The average speed of N₂ molecules at 300 K is about (R = 8.314 J K⁻¹ mol⁻¹):","options":["476 m/s","422 m/s","150 m/s","517 m/s"],"answer":0,"explanation":"u_avg = √(8RT/πM) = √(8 × 8.314 × 300/(3.1416 × 0.028)) ≈ 476 m/s. The rms speed √(3RT/M) is 517 m/s and the most probable speed √(2RT/M) is 422 m/s. Using M = 28 instead of 0.028 kg gives a value 31.6 times too small.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-solutions-states-100","question":"0.1 mol of glucose and 0.05 mol of NaCl (completely dissociated) are dissolved together in 500 g of water. The boiling-point elevation is (Kb = 0.52 K kg mol⁻¹):","options":["0.312 K","0.156 K","0.104 K","0.208 K"],"answer":3,"explanation":"Solute particles = 0.1 (glucose) + 2 × 0.05 (Na⁺ + Cl⁻) = 0.2 mol in 0.5 kg, i.e. 0.4 mol kg⁻¹. ΔTb = 0.52 × 0.4 = 0.208 K. Ignoring the dissociation of NaCl gives 0.156 K.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-101","question":"Under identical conditions an unknown gas takes twice as long as O₂ to effuse through the same orifice. The molar mass of the gas is:","options":["64 g/mol","16 g/mol","128 g/mol","8 g/mol"],"answer":2,"explanation":"t ∝ √M, so √(M/32) = 2 and M = 32 × 4 = 128 g/mol. Taking the time ratio directly proportional to M gives 64.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-102","question":"Seawater may be treated as 0.60 M NaCl (completely dissociated). The minimum pressure needed to desalinate it by reverse osmosis at 300 K is about (R = 0.0821 L atm K⁻¹ mol⁻¹):","options":["2.96 atm","29.6 atm","59.1 atm","14.8 atm"],"answer":1,"explanation":"Reverse osmosis requires a pressure exceeding the osmotic pressure: π = iCRT = 2 × 0.60 × 0.0821 × 300 = 29.6 atm. Ignoring dissociation gives 14.8 atm.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-solutions-states-103","question":"The mass of ethylene glycol (molar mass 62) that must be added to 5.0 kg of water to lower its freezing point to −6.0 °C is about (Kf = 1.86 K kg mol⁻¹):","options":["1.0 kg","500 g","200 g","2.0 kg"],"answer":0,"explanation":"Molality needed = 6.0/1.86 = 3.23 mol kg⁻¹; for 5.0 kg water, n = 16.1 mol, mass = 16.1 × 62 ≈ 1000 g. Forgetting to multiply by the 5 kg of water gives 200 g.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-solutions-states-104","question":"0.1 molal aqueous solution of a weak monobasic acid HA freezes at −0.2046 °C (Kf = 1.86 K kg mol⁻¹). Taking molality ≈ molarity, the dissociation constant of HA is about:","options":["1.0 × 10⁻²","1.0 × 10⁻³","1.1 × 10⁻⁴","1.1 × 10⁻³"],"answer":3,"explanation":"i = ΔTf/(Kf·m) = 0.2046/0.186 = 1.10, so α = i − 1 = 0.10. Ka = Cα²/(1 − α) = 0.1 × 0.01/0.9 = 1.1 × 10⁻³. Neglecting (1 − α) gives 1.0 × 10⁻³.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-solutions-states-105","question":"For CO₂ the van der Waals constants are a = 3.59 L² atm mol⁻² and b = 0.0427 L mol⁻¹. Using Tc = 8a/(27Rb), its critical temperature is about (R = 0.0821 L atm K⁻¹ mol⁻¹):","options":["512 K","152 K","303 K","1024 K"],"answer":2,"explanation":"Tc = 8 × 3.59/(27 × 0.0821 × 0.0427) = 28.72/0.0947 ≈ 303 K, close to the measured 304 K. 1024 K is the Boyle temperature a/(Rb), which is 27/8 times Tc.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-solutions-states-106","question":"The vapour pressure of water at a certain temperature is 17.50 mm Hg. When 18 g of a non-volatile non-electrolyte is dissolved in 90 g of water, the vapour pressure falls to 17.325 mm Hg. The molar mass of the solute is about:","options":["36 g/mol","356 g/mol","178 g/mol","712 g/mol"],"answer":1,"explanation":"Relative lowering = 0.175/17.50 = 0.010 = n/(n + 5), since water = 90/18 = 5 mol. So n = 0.0505 mol and M = 18/0.0505 ≈ 356 g/mol (the dilute approximation n/N gives 360).","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-solutions-states-107","question":"Liquids A (p° = 600 mm Hg) and B (p° = 200 mm Hg) form an ideal solution. The vapour above an equimolar liquid mixture is completely condensed and the condensate is allowed to reach equilibrium with its own vapour. The mole fraction of A in this second vapour is:","options":["0.90","0.75","0.50","0.60"],"answer":0,"explanation":"First vapour: y(A) = 300/(300 + 100) = 0.75. The condensate has x(A) = 0.75, so its vapour has y(A) = 450/(450 + 50) = 0.90. Each evaporation–condensation step enriches the more volatile A, which is the basis of fractional distillation.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-solutions-states-108","question":"A 0.02 molal aqueous solution of a hydrate of formula CrCl₃·6H₂O freezes at −0.1116 °C (Kf = 1.86 K kg mol⁻¹). Assuming complete ionisation, the complex is:","options":["[Cr(H₂O)₄Cl₂]Cl·2H₂O","[Cr(H₂O)₃Cl₃]·3H₂O","[Cr(H₂O)₆]Cl₃","[Cr(H₂O)₅Cl]Cl₂·H₂O"],"answer":3,"explanation":"i = 0.1116/(1.86 × 0.02) = 3, so each formula unit gives three ions: one complex cation and two Cl⁻. That is [Cr(H₂O)₅Cl]²⁺ 2Cl⁻. [Cr(H₂O)₆]Cl₃ would give i = 4 and the dichloro isomer i = 2.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-solutions-states-109","question":"An aqueous solution of a non-volatile non-electrolyte boils at 100.26 °C at 1 atm. Its freezing point is (Kb = 0.52 and Kf = 1.86 K kg mol⁻¹):","options":["−1.86 °C","−0.26 °C","−0.93 °C","−0.48 °C"],"answer":2,"explanation":"Molality = ΔTb/Kb = 0.26/0.52 = 0.50 mol kg⁻¹. Then ΔTf = 1.86 × 0.50 = 0.93 K, so the solution freezes at −0.93 °C. Equivalently, ΔTf/ΔTb = Kf/Kb.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-solutions-states-110","question":"For N₂ the van der Waals constants are a = 1.36 L² atm mol⁻² and b = 0.0318 L mol⁻¹. Its Boyle temperature, T_B = a/(Rb), is about (R = 0.0821 L atm K⁻¹ mol⁻¹):","options":["154 K","521 K","193 K","1042 K"],"answer":1,"explanation":"T_B = 1.36/(0.0821 × 0.0318) ≈ 521 K. At T_B the a and b effects cancel at low pressure and Z ≈ 1 over a wide range. 154 K is the critical temperature 8a/(27Rb), and 193 K is 0.37 T_B.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-solutions-states-111","question":"A dilute aqueous sucrose solution has an osmotic pressure of 2.46 atm at 300 K. Taking molarity ≈ molality, its freezing point is about (R = 0.0821 L atm K⁻¹ mol⁻¹, Kf = 1.86 K kg mol⁻¹):","options":["−0.186 °C","−0.0186 °C","−1.86 °C","−0.372 °C"],"answer":0,"explanation":"C = π/RT = 2.46/(0.0821 × 300) = 0.100 mol L⁻¹ ≈ 0.100 mol kg⁻¹. Sucrose does not ionise, so ΔTf = 1.86 × 0.100 = 0.186 K and the solution freezes at −0.186 °C. Doubling for a non-existent dissociation gives −0.372 °C.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-solutions-states-112","question":"39 g of benzene (molar mass 78) and 46 g of toluene (molar mass 92) form an ideal solution at a temperature where p°(benzene) = 95 mm Hg and p°(toluene) = 30 mm Hg. The total vapour pressure is:","options":["65.0 mm Hg","60.3 mm Hg","125 mm Hg","62.5 mm Hg"],"answer":3,"explanation":"Moles: benzene 0.5, toluene 0.5, so each has x = 0.5. P = 0.5 × 95 + 0.5 × 30 = 62.5 mm Hg. Using mass fractions (0.459 and 0.541) gives 60.3 mm Hg.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-solutions-states-113","question":"A 2 L flask containing NO at 1 atm is connected to a 1 L flask containing O₂ at 1 atm, both at the same temperature. The gases react completely: 2NO + O₂ → 2NO₂. Neglecting dimerisation of NO₂ and assuming constant temperature, the final pressure is:","options":["1.00 atm","0.33 atm","0.67 atm","0.50 atm"],"answer":2,"explanation":"Amounts are proportional to PV: NO = 2 units, O₂ = 1 unit, which react exactly to give 2 units of NO₂. Spread over 3 L, P = 2/3 ≈ 0.67 atm. Without reaction the pressure would stay 1 atm.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-solutions-states-114","question":"How many of the following statements are correct? (A) A solution showing positive deviation from Raoult's law forms a minimum-boiling azeotrope. (B) For an acetone–chloroform mixture, ΔmixH is negative. (C) Henry's law constant (p = K_H·x) of a gas generally increases with temperature, so gas solubility falls on heating. (D) An azeotrope can be separated into its components by simple fractional distillation. (E) Red blood cells placed in 0.5% (w/V) NaCl shrink.","options":["Only two","Only three","Only four","All five"],"answer":1,"explanation":"(A) true. (B) true: hydrogen bonding between acetone and chloroform releases heat (negative deviation). (C) true. (D) false: an azeotrope boils at constant composition. (E) false: 0.5% NaCl is hypotonic relative to blood (≈0.9%), so the cells swell. Three are correct.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-solutions-states-115","question":"Air (80% N₂, 20% O₂ by moles) is held at 2.0 atm and 300 K. Its density is about (R = 0.0821 L atm K⁻¹ mol⁻¹):","options":["2.34 g/L","2.60 g/L","1.17 g/L","2.27 g/L"],"answer":0,"explanation":"Average molar mass = 0.8 × 28 + 0.2 × 32 = 28.8 g/mol. ρ = PM/RT = 2.0 × 28.8/(0.0821 × 300) = 2.34 g/L. Using M = 28 (pure N₂) gives 2.27 g/L.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-solutions-states-116","question":"Mercury(I) nitrate, Hg₂(NO₃)₂, is completely dissociated in a dilute aqueous solution. Its van 't Hoff factor is:","options":["4","2","5","3"],"answer":3,"explanation":"Mercury(I) exists as the dimeric ion Hg₂²⁺ (Hg–Hg bond), so Hg₂(NO₃)₂ → Hg₂²⁺ + 2NO₃⁻ gives three particles, i = 3. Writing it as 2Hg⁺ + 2NO₃⁻ gives the wrong i = 4.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-solutions-states-117","question":"The density of an ideal gas at 127 °C and 2 atm is how many times its density at STP (273 K, 1 atm)?","options":["2.00","0.68","1.37","0.73"],"answer":2,"explanation":"ρ = PM/RT, so ρ₂/ρ₁ = (P₂/P₁)(T₁/T₂) = 2 × 273/400 = 1.37. Doubling the pressure doubles the density, while heating to 400 K reduces it by the factor 273/400.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-solutions-states-118","question":"For a gas at very high pressure the van der Waals equation reduces approximately to P(V − b) = RT, so Z = 1 + Pb/RT. For a gas with b = 0.040 L mol⁻¹ at 500 atm and 300 K, Z is about (R = 0.0821 L atm K⁻¹ mol⁻¹):","options":["1.00","1.81","0.19","1.08"],"answer":1,"explanation":"Z = 1 + Pb/RT = 1 + (500 × 0.040)/(0.0821 × 300) = 1 + 0.81 = 1.81. At such high pressures the excluded volume of the molecules dominates, so Z > 1 and the gas is less compressible than an ideal gas.","difficulty":"very-hard","source":"JEE Main"},
];

export default questions;
